attachment.snippet:
1	// Runs the sample fetch and delivers what came back on a pull request.
2	//
3	// The fetching itself is `dev/tools/fetch-samples.ts`, run as it would be by hand, so
4	// there is one description of how a candidate is fetched rather than a second copy here.
5	// This worker is the part that only makes sense inside a run: reading the operator's
6	// parameters off the item, and turning whatever landed in the working tree into a PR.
7	//
8	// Raw bytes from a site we do not own are exactly what nobody has read yet, so the
9	// delivery carries no automerge and the PR waits for a person.
10	import { execFileSync, spawnSync } from 'node:child_process';
11	import { readFileSync } from 'node:fs';
12	import { join } from 'node:path';
13	import { pathToFileURL } from 'node:url';
14	import { deliverGenerated } from '../../../../../shared/packs/claudinite-tasks/deliver-generated.mjs';
15	
16	const TASK = 'hitbut/fetch-samples';
17	const BRANCH_PREFIX = 'samples';
18	
19	/**
20	 * The operator's parameters, which ride the item's Context — the only channel a task may
21	 * take them from. `force` re-fetches candidates already saved; `only` narrows the run to
22	 * named candidate ids.
23	 */
24	export function argumentsFrom(context) {
25	  const args = [];
26	  for (const line of (context ?? '').split('\n')) {
27	    const [key, ...rest] = line.replace(/^[-*]\s*/, '').split(':');
28	    const value = rest.join(':').trim();
29	    if (key.trim().toLowerCase() === 'force' && /^(true|yes)$/i.test(value)) args.push('--force');
30	    if (key.trim().toLowerCase() === 'only' && value) args.push('--only', value);
31	  }
32	  return args;
33	}
34	
35	/** Paths under the samples tree the fetch changed or created, as git sees them. */
36	export function changedPaths(porcelain) {
37	  return porcelain
38	    .split('\n')
39	    .filter(Boolean)
40	    // Rename entries never occur here: the tool writes and overwrites, it never moves.
41	    .map((line) => line.slice(3).trim())
42	    .filter((path) => path.startsWith('dev/samples/'));
43	}
44	
45	async function main() {
46	  const root = process.env.CLAUDINITE_REPO_ROOT;
47	  const repo = process.env.CLAUDINITE_REPO;
48	  const base = process.env.CLAUDINITE_DEFAULT_BRANCH;
49	  const token = process.env.GITHUB_TOKEN;
50	  if (!token) {
51	    console.error('claudinite-needs-human: action — GITHUB_TOKEN is not set, so nothing can be delivered');
52	    process.exit(1);
53	  }
54	
55	  const args = argumentsFrom(process.env.CLAUDINITE_CONTEXT);
56	  const fetched = spawnSync('node', ['dev/tools/fetch-samples.ts', ...args], { cwd: root, stdio: 'inherit' });
57	  if (fetched.status !== 0) {
58	    // A candidate refusing us is recorded by the tool and is not this: reaching here
59	    // means the tool itself could not run.
60	    console.error(`claudinite-needs-human: failure — the sample fetch exited ${fetched.status}`);
61	    process.exit(1);
62	  }
63	
64	  const porcelain = execFileSync('git', ['status', '--porcelain', '--', 'dev/samples'], { cwd: root, encoding: 'utf8' });
65	  const paths = changedPaths(porcelain);
66	  if (paths.length === 0) {
67	    // Every candidate was already saved: the work ran and found nothing to deliver.
68	    console.log('nothing came back that is not already committed — no pull request to open');
69	    return;
70	  }
71	
72	  const files = Object.fromEntries(paths.map((path) => [path, readFileSync(join(root, path), 'utf8')]));
73	  const pr = await deliverGenerated({
74	    root,
75	    repo,
76	    base,
77	    token,
78	    branchPrefix: BRANCH_PREFIX,
79	    stamp: new Date().toISOString().slice(0, 10),
80	    files,
81	    task: TASK,
82	    message: 'Reconnaissance samples from the candidate list',
83	    title: 'Reconnaissance samples',
84	    body: [
85	      'Raw payloads from the candidate source URLs, for the reconnaissance in #32 to read',
86	      'offline. What each candidate answered — including the ones that refused us — is in',
87	      '`dev/samples/report.GENERATED.md` in this diff.',
88	      '',
89	      'These are bytes from sites hitbut does not own and nobody has read yet, which is why',
90	      'they arrive as a pull request rather than on the default branch.',
91	      '',
92	      'Refs #208, #32',
93	    ].join('\n'),
94	  });
95	  console.log(
96	    `${paths.length} file(s) delivered — ${pr.reused ? 'updated' : 'opened'} PR ` +
97	      `${pr.number !== null ? `#${pr.number}` : `on ${pr.branch}`}`,
98	  );
99	}
100	
101	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
102	  main().catch((error) => {
103	    console.error(`fetch-samples failed: ${error.message}`);
104	    process.exit(1);
105	  });
106	}
